-- Check how many enforcementactions link directly to compliancecase via compref2
SELECT COUNT(*) FROM enforcementactions ea 
JOIN compliancecase cc ON ea.compref2 = cc.compreg;

SELECT COUNT(*) FROM transactionrecord tr
JOIN trader t ON tr.trdref = t.tradereg
WHERE tr.risk_indicators->>'washsus' = 'High';
